-- Comprobación: vendedores, productos y métodos de pago cargados.
select (select count(*) from public.vendors) as vendedores,  -- esperado 5
       (select count(*) from public.products) as productos,  -- esperado 8
       (select count(*) from public.payment_methods) as pagos; -- esperado 11
